begin;
create table public.miller_maintenance_outcomes (id uuid primary key default gen_random_uuid(),cycle_id uuid references public.miller_maintenance_cycles(id) on delete restrict,need_key text not null check(length(need_key)<=180),action_id text not null check(length(action_id)<=100),action_version text not null default 'v1',domain text not null check(domain in ('operations','resource_data','public_health','security')),target_type text not null check(length(target_type)<=80),target_key text not null check(length(target_key)<=180),before_state jsonb not null default '{}'::jsonb,expected_state jsonb not null default '{}'::jsonb,after_state jsonb not null default '{}'::jsonb,verification text not null check(verification in ('passed','failed','inconclusive')),classification text not null check(classification in ('resolved','improved','unchanged','degraded','failed','inconclusive','not_applicable')),started_at timestamptz not null default now(),completed_at timestamptz,evidence_refs jsonb not null default '[]'::jsonb,schema_version text not null default 'maintenance-outcome-v1');
create table public.miller_learning_records (id uuid primary key default gen_random_uuid(),lesson_fingerprint text not null unique check(lesson_fingerprint ~ '^[a-f0-9]{64}$'),domain text not null,lesson_type text not null,scope jsonb not null default '{}'::jsonb,statement text not null check(length(statement)<=500),support_count integer not null default 0,contradiction_count integer not null default 0,status text not null check(status in ('candidate','supported','contradicted','stale','retired')),first_observed_at timestamptz not null default now(),last_confirmed_at timestamptz,evidence_quality text not null default 'verified_outcome',schema_version text not null default 'learning-record-v1');
create table public.miller_growth_opportunities (id uuid primary key default gen_random_uuid(),opportunity_fingerprint text not null unique check(opportunity_fingerprint ~ '^[a-f0-9]{64}$'),domain text not null,gap_type text not null,target_key text not null,reason text not null check(length(reason)<=500),state text not null check(state in ('candidate','prioritized','deferred','in_progress','improved','unchanged','blocked','retired')),priority integer not null check(priority between 0 and 100),first_observed_at timestamptz not null default now(),last_observed_at timestamptz not null default now(),recurrence_count integer not null default 1,evidence_refs jsonb not null default '[]'::jsonb,schema_version text not null default 'growth-opportunity-v1');
alter table public.miller_maintenance_outcomes enable row level security; alter table public.miller_learning_records enable row level security; alter table public.miller_growth_opportunities enable row level security;
create index miller_maintenance_outcomes_cycle_idx on public.miller_maintenance_outcomes(cycle_id,completed_at desc);
create index miller_growth_opportunities_state_priority_idx on public.miller_growth_opportunities(state,priority desc,last_observed_at desc);
create or replace function public.prevent_miller_maintenance_outcome_mutation() returns trigger language plpgsql set search_path=public as $$ begin raise exception 'maintenance outcome evidence is append-only'; end $$;
create trigger miller_maintenance_outcomes_append_only before update or delete on public.miller_maintenance_outcomes for each row execute function public.prevent_miller_maintenance_outcome_mutation();
revoke all on public.miller_maintenance_outcomes,public.miller_learning_records,public.miller_growth_opportunities from public,anon,authenticated;
revoke update,delete,truncate,references,trigger on public.miller_maintenance_outcomes from service_role;
grant select,insert on public.miller_maintenance_outcomes to service_role;
grant select,insert,update on public.miller_learning_records,public.miller_growth_opportunities to service_role;
commit;
